CREATE TABLE projects(
  id bigserial PRIMARY KEY, code text, name text, location text, kind text,
  build_pct double precision, planned_monthly_sales double precision, handover text, land_id bigint, completed bigint DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  org_id text NOT NULL DEFAULT current_setting('app.org_id', true)
  , UNIQUE (org_id, code)
);

CREATE TABLE units(
  id bigserial PRIMARY KEY, project_id bigint REFERENCES projects(id), code text,
  building text, floor bigint, pos bigint, type text, area double precision, view text,
  price double precision, status text CHECK(status IN ('a','r','s')), retained bigint DEFAULT 0, use text DEFAULT 'residential',
  created_at timestamptz NOT NULL DEFAULT now(),
  org_id text NOT NULL DEFAULT current_setting('app.org_id', true)
  , UNIQUE (org_id, code)
);

CREATE TABLE customers(
  id bigserial PRIMARY KEY, name text, phone text, created text, rescheduled bigint DEFAULT 0,
  id_type text, id_number text, nationality text, id_expiry text, dob text, pep bigint DEFAULT 0,
  source_of_funds text, kyc_status text DEFAULT 'pending', kyc_risk text, kyc_note text, kyc_at text,
  consent_at text, email text, consent_version text, consent_source text, erased_at text,
  created_at timestamptz NOT NULL DEFAULT now(),
  org_id text NOT NULL DEFAULT current_setting('app.org_id', true)
);

CREATE TABLE leads(
  id bigserial PRIMARY KEY, name text, phone text, interest text, project_id bigint REFERENCES projects(id),
  channel text, stage bigint, interactions bigint, budget double precision, created text, last_contact text, score bigint,
  broker_id bigint, bedrooms bigint,
  created_at timestamptz NOT NULL DEFAULT now(),
  org_id text NOT NULL DEFAULT current_setting('app.org_id', true)
);

CREATE TABLE bookings(
  id bigserial PRIMARY KEY, unit_id bigint REFERENCES units(id), customer_id bigint REFERENCES customers(id),
  lead_id bigint, plan text, price double precision, status text CHECK(status IN ('pending','confirmed','cancelled')),
  created text, expires text, broker_id bigint, list_price double precision, handed_over text,
  created_at timestamptz NOT NULL DEFAULT now(),
  org_id text NOT NULL DEFAULT current_setting('app.org_id', true)
);

CREATE TABLE installments(
